svg.script:
// Utility to animate a dot along an SVG path
function animateAlongPath(dot, path, duration, opts = {}) {
  return new Promise(resolve => {
    const total = path.getTotalLength();
    const start = performance.now();
    const easing = opts.easing || ((t)=>t); // linear by default

    function frame(now) {
      let t = Math.min(1, (now - start) / duration);
      t = easing(t);
      const pt = path.getPointAtLength(total * t);
      dot.setAttribute('cx', pt.x);
      dot.setAttribute('cy', pt.y);
      if (t < 1) requestAnimationFrame(frame);
      else resolve();
    }
    requestAnimationFrame(frame);
  });
}

// Blink helpers
function blinkRect(g, cls, ms=800) {
  const rect = g.querySelector('rect');
  rect.classList.add(cls, 'blink');
  return new Promise(res => setTimeout(()=>{
    rect.classList.remove('blink');
    res();
  }, ms));
}
function setRectState(g, state /* '', 'ok', 'err' */) {
  const rect = g.querySelector('rect');
  rect.classList.remove('ok','err','blink');
  if (state) rect.classList.add(state);
}

// Highlight path while active
function highlightPath(path, ms) {
  path.classList.add('highlight');
  return new Promise(res => setTimeout(()=>{
    path.classList.remove('highlight');
    res();
  }, ms));
}

// Small pause
const wait = (ms)=>new Promise(res=>setTimeout(res,ms));

// Elements
const dotA = document.getElementById('dotA');
const dotB = document.getElementById('dotB');

const pClientProxy = document.getElementById('p-client-proxy');
const pProxyKey1  = document.getElementById('p-proxy-key1');
const pProxyKey2  = document.getElementById('p-proxy-key2');
const pProxyKey3  = document.getElementById('p-proxy-key3');
const pKey1OR = document.getElementById('p-key1-or');
const pKey2OR = document.getElementById('p-key2-or');
const pKey3OR = document.getElementById('p-key3-or');

const key1 = document.getElementById('key1');
const key2 = document.getElementById('key2');
const key3 = document.getElementById('key3');
const openrouter = document.getElementById('openrouter-shape');

const badge429 = document.getElementById('badge-429');
const badgeOK  = document.getElementById('badge-ok');

function show(el) { el.setAttribute('visibility','visible'); }
function hide(el) { el.setAttribute('visibility','hidden'); }

// Easing
const ease = t => 1 - Math.pow(1-t, 3);

async function requestA() {
  // Client -> Proxy
  await highlightPath(pClientProxy, 700);
  await animateAlongPath(dotA, pClientProxy, 700, {easing:ease});

  // Proxy -> Key2
  await highlightPath(pProxyKey2, 600);
  await animateAlongPath(dotA, pProxyKey2, 600, {easing:ease});

  // Key2 -> OpenRouter (first attempt -> 429)
  await highlightPath(pKey2OR, 900);
  await animateAlongPath(dotA, pKey2OR, 900, {easing:ease});

  // Error: blink Key2 red, show 429 near OR
  setRectState(key2,'err');
  show(badge429);
  await blinkRect(key2,'err',900);
  setRectState(key2,'');

  // Retry: backoff, then Key2 -> OpenRouter success
  await wait(500);
  await highlightPath(pKey2OR, 900);
  await animateAlongPath(dotA, pKey2OR, 900, {easing:ease});

  // Success: blink Key2 and OR green, show 200 OK
  setRectState(key2,'ok');
  openrouter.classList.add('ok','blink');
  hide(badge429);
  show(badgeOK);
  await wait(800);
  setRectState(key2,'');
  openrouter.classList.remove('ok','blink');
  hide(badgeOK);

  // Return dot to client start (invisibly)
  dotA.setAttribute('cx','200'); dotA.setAttribute('cy','129');
}

async function requestB() {
  // Client -> Proxy
  await highlightPath(pClientProxy, 700);
  await animateAlongPath(dotB, pClientProxy, 700, {easing:ease});

  // Proxy -> Key3
  await highlightPath(pProxyKey3, 600);
  await animateAlongPath(dotB, pProxyKey3, 600, {easing:ease});

  // Key3 -> OpenRouter success
  await highlightPath(pKey3OR, 900);
  await animateAlongPath(dotB, pKey3OR, 900, {easing:ease});

  // Success blinks
  setRectState(key3,'ok');
  openrouter.classList.add('ok','blink');
  show(badgeOK);
  await wait(800);
  setRectState(key3,'');
  openrouter.classList.remove('ok','blink');
  hide(badgeOK);

  // Reset
  dotB.setAttribute('cx','200'); dotB.setAttribute('cy','129');
}

// Orchestrate loop: A (429->retry->200), then B (200), then pause and repeat with rotation
async function loop() {
  while (true) {
    await wait(400);
    await requestA();
    await wait(600);
    await requestB();
    await wait(1200);
  }
}

// Start
loop();
